        <section className="product-layout" aria-label="Trail Runner 2 product">
          <div className="product-gallery">
            <div className="gallery-heading"><span>TRAIL COLLECTION</span><span>{String(slideIndex + 1).padStart(2, '0')} / 03</span></div>
            <div className="carousel" role="region" aria-roledescription="carousel" aria-label="Product photos" aria-live="polite">
              {slides.map((slide, index) => (
                <div key={slide.label} className={`slide ${index === slideIndex ? 'is-active' : ''}`} role="group" aria-roledescription="slide" aria-label={`${index + 1} of ${slides.length}`} aria-hidden={index !== slideIndex}>
                  <ShoeArtwork slide={{ ...slide, accent: color === 'Black' ? '#252a2b' : color === 'Grey' ? '#888d8a' : slide.accent }} />
                </div>
              ))}
              <button className="carousel-control previous" aria-label="Previous photo" onClick={() => setSlideIndex((slideIndex + slides.length - 1) % slides.length)}>←</button>
              <button className="carousel-control next" aria-label="Next photo" onClick={() => setSlideIndex((slideIndex + 1) % slides.length)}>→</button>
              <div className="carousel-dots" aria-label="Photo selection">
                {slides.map((slide, index) => <button key={slide.label} aria-label={`Show photo ${index + 1}`} aria-current={index === slideIndex} onClick={() => setSlideIndex(index)} />)}
              </div>
              <button className="rotation-control" aria-label="Pause slideshow">Ⅱ</button>
            </div>
            <p className="gallery-note">Designed for the path less travelled.</p>
          </div>

          <div className="product-info">
            <p className="eyebrow">STRIDE / OUTDOOR</p>
            <div className="title-row">
              <h1>Trail Runner 2</h1>
              <button className={`heart-button ${wishlist ? 'saved' : ''}`} aria-label={wishlist ? 'Remove from wishlist' : 'Add to wishlist'} aria-pressed={wishlist} onClick={() => setWishlist(!wishlist)}>{wishlist ? '♥' : '♡'}</button>
            </div>
            <p className="tagline">Go further. Feel lighter.</p>
            <div className="price-row"><span className="price">$148</span><button className="tax-info" aria-label="Taxes included" aria-describedby="tax-tooltip">i</button><span className="tax-tooltip" role="tooltip" id="tax-tooltip">Price includes taxes</span><span className="tax-copy">Taxes included</span></div>
            <p className="description">A dependable trail companion with a featherlight feel. Built with responsive cushioning, confident grip and a weather-ready upper for whatever is around the bend.</p>

            <fieldset className="choice-group">
              <legend>Color <strong>{color}</strong></legend>
              <div className="color-options" role="radiogroup" aria-label="Color">
                {colors.map((item) => <label key={item.name} className="color-option"><input type="radio" name="color" value={item.name} checked={color === item.name} onChange={() => setColor(item.name)} /><span className={`swatch ${item.className}`} /> <span>{item.name}</span></label>)}
              </div>
            </fieldset>

            <div className="size-heading"><label htmlFor="size">Size <strong>{size || 'Select a size'}</strong></label><button ref={sizeGuideTrigger} className="text-button" onClick={() => setGuideOpen(true)}>Size guide <span>↗</span></button></div>
            <select id="size" className="size-select" aria-label="Size" value={size} onChange={(event) => setSize(event.target.value)}>
              <option value="">Choose your size</option><option value="7">7</option><option value="8">8</option><option value="9">9</option><option value="10" disabled>10 — Sold out</option><option value="11">11</option>
            </select>

            <div className="purchase-row">
              <div className="quantity-control"><button aria-label="Decrease quantity" onClick={() => changeQuantity(-1)}>-</button><input aria-label="Quantity" type="number" min="1" value={quantity} onChange={(event) => setQuantity(Math.max(1, Number(event.target.value) || 1))} /><button aria-label="Increase quantity" onClick={() => changeQuantity(1)}>+</button></div>
              <button className="add-button" onClick={addToCart}>Add to cart <span>→</span></button>
            </div>
            <p className="status-message" role="status" aria-live="polite">{status}</p>
            <div className="perks"><span>◌ Free shipping over 100 dollars</span><span>↺ 30-day returns</span></div>
          </div>
        </section>

        <section className="information-section" aria-label="Product information">
          <div className="tab-list" role="tablist" aria-label="Product information">
            {['details', 'reviews', 'shipping'].map((tab) => <button key={tab} id={`tab-${tab}`} role="tab" aria-controls="product-tabpanel" aria-selected={activeTab === tab} tabIndex={activeTab === tab ? 0 : -1} className={activeTab === tab ? 'active' : ''} onClick={() => setActiveTab(tab)}>{tab[0].toUpperCase() + tab.slice(1)}{tab === 'reviews' && <small> (24)</small>}</button>)}
          </div>
          <div className="tab-panel" id="product-tabpanel" role="tabpanel" aria-labelledby={`tab-${activeTab}`}>
            {activeTab === 'details' && <><h2>Made for the wild in you.</h2><p>Trail Runner 2 pairs a breathable recycled mesh upper with a grippy all-terrain sole. A padded collar and our softest foam keep every mile comfortable.</p><div className="feature-list"><span>01 / Recycled mesh upper</span><span>02 / All-terrain rubber grip</span><span>03 / Responsive foam cushioning</span></div></>}
            {activeTab === 'reviews' && <><h2>Loved on the long way round.</h2><p>“The grip is incredible and they felt broken-in on day one.” — Maya R., verified runner</p><p className="stars">★★★★★ <span>4.8 average from 24 reviews</span></p></>}
            {activeTab === 'shipping' && <><h2>Easy miles, easy returns.</h2><p>Enjoy free standard shipping on orders over $100. If they are not the right fit, return unworn shoes within 30 days.</p></>}
          </div>
        </section>

        <section className="faq-section" aria-label="Common questions">
          <div><p className="eyebrow">NEED TO KNOW</p><h2>Common questions</h2></div>
          <div className="faq-list">
            {['Are Trail Runner 2 true to size?', 'Can I wear these in wet weather?', 'How do I clean my Trail Runner 2?'].map((question, index) => <div className="faq-item" key={question}><button id={`question-${index}`} aria-controls={`answer-${index}`} aria-expanded={openQuestion === index} onClick={() => setOpenQuestion(openQuestion === index ? null : index)}><span>{question}</span><b>{openQuestion === index ? '−' : '+'}</b></button><div className="faq-answer" id={`answer-${index}`} role="region" aria-labelledby={`question-${index}`} hidden={openQuestion !== index}><p>{index === 0 ? 'Yes, we recommend choosing your usual running shoe size.' : index === 1 ? 'The water-resistant upper handles light rain and puddles with ease.' : 'Brush off dry dirt, then gently wipe with cool water and mild soap.'}</p></div></div>)}
          </div>
        </section>
      </main>

      {guideOpen && <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && closeGuide()}><div className="size-modal" role="dialog" aria-modal="true" aria-labelledby="size-guide-title"><button ref={modalClose} className="modal-close" aria-label="Close size guide" onClick={closeGuide}>×</button><p className="eyebrow">FIND YOUR FIT</p><h2 id="size-guide-title">Size guide</h2><p>Measure from heel to longest toe while standing. We’ll recommend your best fit.</p><label htmlFor="foot-length">Foot length</label><div className="measure-row"><input id="foot-length" aria-label="Foot length" type="number" min="20" max="35" placeholder="26" value={footLength} onChange={(event) => setFootLength(event.target.value)} /><select aria-label="Unit or system" value={unit} onChange={(event) => setUnit(event.target.value)}><option value="us">US</option><option value="eu">EU</option></select></div>{footLength && <div className="recommendation" role="status">Your recommended {unit.toUpperCase()} size is <strong>{unit === 'us' ? '9' : '42'}</strong>.</div>}<div className="size-table"><span>US</span><span>EU</span><span>Foot length</span><b>8</b><b>41</b><b>25.5 cm</b><b>9</b><b>42</b><b>26.0 cm</b><b>10</b><b>43</b><b>27.0 cm</b></div><button className="modal-done" onClick={closeGuide}>Done</button></div></div>}

      <footer className="site-footer" role="contentinfo"><div className="footer-top"><a className="logo" href="/">Stride<span>.</span></a><p>Make your own way.</p><div className="newsletter"><label htmlFor="email">Get trail notes in your inbox</label><div><input id="email" type="email" placeholder="Your email address" /><button aria-label="Subscribe">→</button></div></div></div><div className="footer-links"><div><h3>Help</h3><a href="#contact">Customer service</a><a href="#shipping">Shipping & returns</a><a href="#faq">FAQ</a></div><div><h3>Company</h3><a href="#about">About Stride</a><a href="#journal">Journal</a><a href="#careers">Careers</a></div><div><h3>Follow along</h3><a href="#instagram">Instagram</a></div></div><div className="footer-bottom"><span>© 2025 Stride Running Co.</span><span>Made for moving outside.</span><span>Privacy&nbsp;&nbsp;&nbsp; Terms</span></div></footer>
    </div>
  )
